INSERT INTO app.categories (id, name, description, max_loan_days, usage_guidelines, is_specialised, auto_approval_enabled) OVERRIDING SYSTEM VALUE VALUES
    (1, 'Laptops', 'Portable computers for business trips and temporary replacements.', 14, 'Business trips, temporary replacement of a broken work laptop, presentations and training outside the office.', false, true),
    (2, 'Projectors', 'Projectors for meeting rooms and events.', 5, 'Presentations in meeting rooms, client meetings, training sessions and internal events.', false, true),
    (3, 'Cameras', 'Photo and video cameras.', 7, 'Recording interviews, events, product photos and site documentation for work purposes.', false, true),
    (4, 'Audio recorders', 'Portable audio recorders.', 7, 'Recording interviews, meetings with consent of the participants, and field audio for work projects.', false, true),
    (5, 'Microphones', 'Wireless and USB microphones.', 7, 'Presentations, webinars, recording of training videos and events.', false, true),
    (6, 'Conference kits', 'Speakerphones and video bars for remote meetings.', 5, 'Remote meetings with clients and colleagues in rooms without built-in conference equipment.', false, true),
    (7, 'Tablets', 'Tablets for demonstrations and field work.', 10, 'Product demonstrations, digital forms during site visits and testing of applications.', false, true),
    (8, 'Monitors', 'Additional displays for temporary workplaces.', 30, 'Temporary second screen at a workplace, onboarding of new employees and hot desks.', false, true),
    (9, 'Headsets', 'Headsets for calls and training.', 14, 'Calls with clients, online training and work in open spaces.', false, true),
    (10, 'Measuring instruments', 'Calibrated measuring instruments.', 7, 'Measurements on customer sites and in the laboratory by trained employees.', true, true),
    (11, 'Test devices', 'Smartphones and devices for software testing.', 14, 'Testing of mobile applications and websites on real devices.', false, true),
    (12, 'Drones', 'Camera drones for site inspections.', 3, 'Site inspections and aerial photos by certified pilots in permitted areas only.', true, true),
    (13, 'Lighting', 'Portable lights for photo and video.', 7, 'Lighting for video recordings, photo shoots and events.', false, true),
    (14, 'Network test tools', 'Tools for testing cabling and networks.', 5, 'Network diagnostics and cable certification by IT staff.', true, true);
